  ('hotel-nhat-phuong', 'homestays/hotel-nhat-phuong/25240e3f71fa85d0.jpg', 'https://mbmliqykqjufvngjvdjx.supabase.co/storage/v1/object/public/viettrek-media/homestays/hotel-nhat-phuong/25240e3f71fa85d0.jpg', 0),
  ('hotel-nhat-phuong', 'homestays/hotel-nhat-phuong/a930e2edcb5ef75f.jpg', 'https://mbmliqykqjufvngjvdjx.supabase.co/storage/v1/object/public/viettrek-media/homestays/hotel-nhat-phuong/a930e2edcb5ef75f.jpg', 1),
  ('hotel-nhat-phuong', 'homestays/hotel-nhat-phuong/d2754cc5086217c8.jpg', 'https://mbmliqykqjufvngjvdjx.supabase.co/storage/v1/object/public/viettrek-media/homestays/hotel-nhat-phuong/d2754cc5086217c8.jpg', 2),
  ('hotel-nhat-phuong', 'homestays/hotel-nhat-phuong/e7c865be67d0610e.jpg', 'https://mbmliqykqjufvngjvdjx.supabase.co/storage/v1/object/public/viettrek-media/homestays/hotel-nhat-phuong/e7c865be67d0610e.jpg', 3),
  ('hotel-nhat-phuong', 'homestays/hotel-nhat-phuong/a15872a2324d52e8.jpg', 'https://mbmliqykqjufvngjvdjx.supabase.co/storage/v1/object/public/viettrek-media/homestays/hotel-nhat-phuong/a15872a2324d52e8.jpg', 4)
) AS v(slug, storage_key, public_url, sort_order)
JOIN place p ON p.slug = v.slug
JOIN media_asset m ON m.storage_key = v.storage_key
WHERE NOT EXISTS (SELECT 1 FROM place_media pm WHERE pm.place_id = p.id AND pm.media_id = m.id);

COMMIT;

SELECT p.slug, p.name, COUNT(pm.media_id) AS so_anh, SUM(CASE WHEN pm.role = 'COVER' THEN 1 ELSE 0 END) AS cover
FROM place p LEFT JOIN place_media pm ON pm.place_id = p.id
WHERE p.slug IN ('homestay-anh-tuc','new-highland-hotel','hoa-son-tra-hotel','nha-nghi-duy-vu','homestay-hoa-thao','homestay-cuong-tu','homestay-bao-lan','win-homestay','pu-nhu-house','co-gai-thai-homestay','moc-homestay','bungalow-xuan-giang','hotel-thuat-hoa','chelly-hotel','hanh-phuc-creek-homestay','hotel-nhat-phuong')
GROUP BY p.slug, p.name ORDER BY p.name;
